407	func TestEstimateCurrentBillOverflow(t *testing.T) {
408		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
409	
410		// 月费 maxInt64、1 单位超额即让税前合计溢出。
411		mustPlan(t, s, Plan{ID: "p-sum", MonthlyFee: maxInt64, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
412		mustAccount(t, s, "a")
413		if err := s.Subscribe("a", "p-sum", utc(2026, 1, 10, 0, 0)); err != nil {
414			t.Fatal(err)
415		}
416		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 12, 0, 0), Quantity: 1}); err != nil {
417			t.Fatal(err)
418		}
419		if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrOverflow) {
420			t.Fatalf("subtotal overflow: %v", err)
421		}
422	
423		// 税前合法、含税总额溢出。
424		mustPlan(t, s, Plan{ID: "p-tax", MonthlyFee: 9000000000000000000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
425		mustAccount(t, s, "b")
426		if err := s.Subscribe("b", "p-tax", utc(2026, 1, 10, 0, 0)); err != nil {
427			t.Fatal(err)
428		}
429		if _, err := s.EstimateCurrentBill("b"); !errors.Is(err, ErrOverflow) {
430			t.Fatalf("total overflow: %v", err)
431		}
432	
433		// 溢出时不返回部分金额、不留账单、不改用量，可重试。
434		if _, err := s.GetBill("a", jan(2026)); !errors.Is(err, ErrBillNotFound) {
435			t.Fatalf("overflow left a bill: %v", err)
436		}
437		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 1 {
438			t.Fatalf("usage changed: %d", u.Total)
439		}
440		if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrOverflow) {
441			t.Fatal("retry estimate lost overflow")
442		}
443	
444		// 计税中间乘积可超 int64，但最终金额合法时预估必须精确完成。
445		mustPlan(t, s, Plan{ID: "p-large", MonthlyFee: 8000000000000000005, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
446		mustAccount(t, s, "c")
447		if err := s.Subscribe("c", "p-large", utc(2026, 1, 10, 0, 0)); err != nil {
448			t.Fatal(err)
449		}
450		e, err := s.EstimateCurrentBill("c")
451		if err != nil {
452			t.Fatalf("large but legal estimate: %v", err)
453		}
454		if e.MonthlyFee != 8000000000000000005 || e.Tax != 800000000000000001 || e.EstimatedTotalDue != 8800000000000000006 {
455			t.Fatalf("large estimate amounts: %+v", e)
456		}
457	
458		// 时钟推进不影响上述判断的独立性（避免 unused 警告，同时验证跨月后
459		// 一月仍未因预估而关闭：二月账户 c 的预估是零用量整月费）。
460		clk.t = utc(2026, 2, 1, 0, 0)
461		if _, err := s.GetBill("c", jan(2026)); !errors.Is(err, ErrBillNotFound) {
462			t.Fatalf("january bill should not exist after estimates")
463		}
464	}
